CREATE TABLE "printer_spools" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "printer_spools_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"printer_id" integer NOT NULL,
	"tool" integer DEFAULT 0 NOT NULL,
	"spool_id" integer NOT NULL
);
