-- Each printer's loaded spool becomes the spool on its first tool.
INSERT INTO "printer_spools" ("printer_id", "tool", "spool_id")
SELECT "id", 0, "spool_id" FROM "printers" WHERE "spool_id" IS NOT NULL;--> statement-breakpoint
-- A print being tracked carries on: its counter and start point move into the job column.
UPDATE "printers" SET "job" = jsonb_build_object(
  'key', "job_file",
  'file', "job_file",
  'counter', "job_last_mm",
  'amounts', jsonb_build_array("job_last_mm"),
  'bases', jsonb_build_array("job_base_mm"),
  'entries', CASE WHEN "job_usage_id" IS NOT NULL AND "spool_id" IS NOT NULL
    THEN jsonb_build_array(jsonb_build_object('tool', 0, 'spoolId', "spool_id", 'usageId', "job_usage_id"))
    ELSE '[]'::jsonb END
) WHERE "job_file" IS NOT NULL;
